def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings"""
    # Find first position where they differ
    min_len = min(len(s_in), len(s_out))

    # Check for character substitutions
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if we're replacing a single character
            if len(s_in) == len(s_out):
                return (s_in[i], s_out[i], i)
            elif len(s_in) < len(s_out):
                # Insertion case
                return (s_in[i], s_out[i], i)
            else:
                # Deletion case  
                return (s_in[i], "", i)

    # If we've gone through all common positions, check length difference
    if len(s_in) != len(s_out):
        if len(s_in) < len(s_out):
            # Insert at end
            return (s_in[-1] if s_in else "", s_out[-1], len(s_in))
        else:
            # Delete at end
            return (s_in[-1], "", len(s_in)-1)

    return ("", "", -1)

def propose_rule_candidates(s_in, s_out):
    """Propose rule candidates based on minimal edit"""
    # This is a simplified version - in reality this would be more complex
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

