    # Try substring replacement
    if len(s_in) > 1 and len(s_out) > 1:
        # Try replacing first few characters
        candidates.append((s_in[:min(3, len(s_in))], s_out[:min(3, len(s_out))]))

    # Try more general patterns
    candidates.append((s_in, s_out))

    return candidates

